command:example.dev:code:
# エクスポートして以前のバックアップと比較する
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "新しいスクリプト: $($new.Count) | 削除されたスクリプト: $($removed.Count)"

$config = Get-ColorScriptConfiguration
if ($config.Startup.AutoShowOnImport) {
    Write-Host "起動スクリプトが有効になっています"
}

$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "設定されたカスタム キャッシュ パス: $($config.Cache.Path)"
} else {
    Write-Host "デフォルトのキャッシュパスの使用"
}

Write-Host "有効なキャッシュ パス: $($config.Cache.EffectivePath)"

# フィルタリングされたスクリプトのキャッシュを構築する
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# パターンに一致する最初のスクリプトを検索して簡単に表示します
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# 自動化を実行する前に、参照されているスクリプトがすべて存在することを確認してください
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "不足しているスクリプト: $($missing -join ', ')"
} else {
    Write-Host "必要なスクリプトはすべて利用可能です"
}

# プロジェクトに複数のカラースクリプトを作成する
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "$($scriptNames.Count) カラースクリプト テンプレートを作成しました"

# スクリプト名の規則を確認する
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "無効な名前「$name」: $_"
    }
}

# カテゴリとタグの検証を使用して作成する
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "レトロ カテゴリが見つかりません"
}

# リセットが成功したことを確認する
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "構成がプラットフォームのデフォルトに正常にリセットされました"
} else {
    Write-Host "構成はリセットされましたが、カスタム パスを使用しました: $($config.Cache.Path)"
}

# 幾何学的なカラースクリプトのスライドショーを作成する
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# エラー処理例
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "スクリプトが見つかりません: $_"
    Show-ColorScript  # ランダムへのフォールバック
}

# ビルド自動化の統合
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # インタラクティブな使用のためのランダム表示
}

# ターミナル グリーティングのスケジュールされたタスク
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
